import java.util.*;

public class Main {
    public static void main(String[] args) {
        // Two states, no per-state behaviour: an enum-style transition table is enough (no State classes)
        Map<String, String> table = new HashMap<>();
        table.put("LOCKED|coin", "UNLOCKED"); table.put("LOCKED|push", "LOCKED");
        table.put("UNLOCKED|push", "LOCKED"); table.put("UNLOCKED|coin", "UNLOCKED");
        String state = "LOCKED";
        for (String event : new String[] {"push", "coin", "coin", "push", "push"}) {
            String next = table.get(state + "|" + event); // one lookup replaces a class per state
            System.out.println(String.format("%-9s + %-4s -> %s", state, event, next));
            state = next;
        }
        System.out.println("final: " + state);
    }
}

