import java.util.*;

public class Main {
    public static void main(String[] args) {
        // One state field: illegal combos (moving with doors open) cannot exist
        int floor = 0, timer = 0;
        String state = "IDLE";
        TreeSet<Integer> stops = new TreeSet<>(List.of(2, 3));
        System.out.println("stops: " + stops);
        for (int t = 1; t <= 8; t++) {
            if (state.equals("IDLE")) {
                if (stops.contains(floor)) { stops.remove(floor); state = "DOORS_OPEN"; timer = 1; }
                else if (!stops.isEmpty()) state = stops.first() > floor ? "MOVING_UP" : "MOVING_DOWN";
            } else if (state.startsWith("MOVING")) {
                floor += state.equals("MOVING_UP") ? 1 : -1;
                if (stops.contains(floor)) { stops.remove(floor); state = "DOORS_OPEN"; timer = 1; } // stop if requested
            } else if (state.equals("DOORS_OPEN")) {
                if (--timer == 0) state = "IDLE";
            }
            System.out.println("t=" + t + " floor=" + floor + " " + state);
        }
    }
}

