import java.util.*;

public class Main {
    static final int START = 5, TOP = 9;

    static int travel(List<Integer> path) {
        int pos = START, total = 0;
        for (int f : path) { total += Math.abs(f - pos); pos = f; }
        return total;
    }

    static List<Integer> sstf(List<Integer> r) {
        List<Integer> left = new ArrayList<>(r), out = new ArrayList<>();
        int pos = START;
        while (!left.isEmpty()) {
            int best = left.get(0);
            for (int f : left) {
                int d = Math.abs(f - pos), bd = Math.abs(best - pos);
                if (d < bd || (d == bd && f > best)) best = f; // nearest; ties go higher
            }
            left.remove(Integer.valueOf(best)); out.add(best); pos = best;
        }
        return out;
    }

    public static void main(String[] args) {
        List<Integer> reqs = List.of(8, 2, 6, 1, 4);
        List<Integer> up = new ArrayList<>(), down = new ArrayList<>();
        for (int f : reqs) if (f >= START) up.add(f); else down.add(f);
        Collections.sort(up);
        down.sort(Collections.reverseOrder());
        List<Integer> look = new ArrayList<>(up); look.addAll(down); // reverses at the last request
        List<Integer> scan = new ArrayList<>(up); scan.add(TOP); scan.addAll(down); // goes to the end floor
        System.out.println("start " + START + " requests " + reqs);
        String[] names = {"FCFS", "SSTF", "SCAN", "LOOK"};
        List<List<Integer>> paths = List.of(reqs, sstf(reqs), scan, look);
        for (int i = 0; i < 4; i++)
            System.out.println(names[i] + " " + paths.get(i) + " -> " + travel(paths.get(i)) + " floors");
    }
}

