// Total floors travelled by FCFS, SSTF, SCAN and LOOK (start floor 5 going up, top floor 9)
const START = 5, TOP = 9;
const reqs = [8, 2, 6, 1, 4];

function travel(path) {
  let pos = START, total = 0;
  for (const f of path) { total += Math.abs(f - pos); pos = f; }
  return total;
}

function sstf(r) {
  const left = [...r], out = [];
  let pos = START;
  while (left.length) {
    let best = left[0];
    for (const f of left) {
      const d = Math.abs(f - pos), bd = Math.abs(best - pos);
      if (d < bd || (d === bd && f > best)) best = f; // nearest; ties go higher
    }
    left.splice(left.indexOf(best), 1); out.push(best); pos = best;
  }
  return out;
}

const up = reqs.filter(f => f >= START).sort((a, b) => a - b);
const down = reqs.filter(f => f < START).sort((a, b) => b - a);
const paths = [["FCFS", reqs], ["SSTF", sstf(reqs)],
  ["SCAN", [...up, TOP, ...down]], // sweeps to the end floor before reversing
  ["LOOK", [...up, ...down]]];     // reverses at the last request
console.log("start " + START + " requests [" + reqs.join(", ") + "]");
for (const [name, p] of paths) console.log(name + " [" + p.join(", ") + "] -> " + travel(p) + " floors");

