#include <bits/stdc++.h>
using namespace std;
const int START = 5, TOP = 9;

int travel(const vector<int>& path) {
    int pos = START, total = 0;
    for (int f : path) { total += abs(f - pos); pos = f; }
    return total;
}

vector<int> sstf(vector<int> left) {
    vector<int> out;
    int pos = START;
    while (!left.empty()) {
        int bi = 0;
        for (int i = 0; i < (int)left.size(); i++) {
            int d = abs(left[i] - pos), bd = abs(left[bi] - pos);
            if (d < bd || (d == bd && left[i] > left[bi])) bi = i; // nearest; ties go higher
        }
        pos = left[bi]; out.push_back(pos); left.erase(left.begin() + bi);
    }
    return out;
}

string show(const vector<int>& v) {
    string s = "[";
    for (size_t i = 0; i < v.size(); i++) s += (i ? ", " : "") + to_string(v[i]);
    return s + "]";
}

int main() {
    vector<int> reqs = {8, 2, 6, 1, 4}, up, down;
    for (int f : reqs) (f >= START ? up : down).push_back(f);
    sort(up.begin(), up.end());
    sort(down.rbegin(), down.rend());
    vector<int> look = up; look.insert(look.end(), down.begin(), down.end()); // reverses at last request
    vector<int> scan = up; scan.push_back(TOP); scan.insert(scan.end(), down.begin(), down.end()); // end floor first
    cout << "start " << START << " requests " << show(reqs) << endl;
    vector<pair<string, vector<int>>> paths = {{"FCFS", reqs}, {"SSTF", sstf(reqs)}, {"SCAN", scan}, {"LOOK", look}};
    for (auto& p : paths) cout << p.first << " " << show(p.second) << " -> " << travel(p.second) << " floors" << endl;
}

