using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    const int START = 5, TOP = 9;

    static int Travel(List<int> path)
    {
        int pos = START, total = 0;
        foreach (int f in path) { total += Math.Abs(f - pos); pos = f; }
        return total;
    }

    static List<int> Sstf(List<int> r)
    {
        List<int> left = new List<int>(r), outp = new List<int>();
        int pos = START;
        while (left.Count > 0)
        {
            int best = left[0];
            foreach (int f in left)
            {
                int d = Math.Abs(f - pos), bd = Math.Abs(best - pos);
                if (d < bd || (d == bd && f > best)) best = f; // nearest; ties go higher
            }
            left.Remove(best); outp.Add(best); pos = best;
        }
        return outp;
    }

    static string Show(List<int> v) { return "[" + string.Join(", ", v) + "]"; }

    static void Main()
    {
        List<int> reqs = new List<int> { 8, 2, 6, 1, 4 };
        List<int> up = reqs.Where(f => f >= START).OrderBy(f => f).ToList();
        List<int> down = reqs.Where(f => f < START).OrderByDescending(f => f).ToList();
        List<int> look = up.Concat(down).ToList();                     // reverses at the last request
        List<int> scan = up.Concat(new[] { TOP }).Concat(down).ToList(); // goes to the end floor first
        Console.WriteLine("start " + START + " requests " + Show(reqs));
        string[] names = { "FCFS", "SSTF", "SCAN", "LOOK" };
        List<int>[] paths = { reqs, Sstf(reqs), scan, look };
        for (int i = 0; i < 4; i++)
            Console.WriteLine(names[i] + " " + Show(paths[i]) + " -> " + Travel(paths[i]) + " floors");
    }
}

