public class Main {
    static final int INF = 1000000, CALL = 6;

    static int cost(int floor, String dir, int stops, boolean maint) {
        if (maint) return INF;                       // out of service
        int d = Math.abs(floor - CALL);
        int base = (dir.equals("IDLE") || (dir.equals("UP") && floor <= CALL))
            ? d        // can reach the caller on the way
            : d + 20;  // must finish its sweep and come back
        return base + 10 * stops;                    // each assigned stop costs about 10 s
    }

    public static void main(String[] args) {
        // Dispatcher picks the car with the lowest estimated cost for an UP call at floor 6
        String[] names = {"A", "B", "C", "D"};
        int[] floors = {1, 3, 7, 6};
        String[] dirs = {"IDLE", "UP", "DOWN", "IDLE"};
        int[] stops = {0, 1, 0, 0};
        boolean[] maint = {false, false, false, true};
        int cheapest = 0, nearest = 0, bestCost = Integer.MAX_VALUE;
        for (int i = 0; i < 4; i++) {
            int v = cost(floors[i], dirs[i], stops[i], maint[i]);
            System.out.println("car " + names[i] + " cost " + (v >= INF ? "INF" : String.valueOf(v)));
            if (v < bestCost) { bestCost = v; cheapest = i; }
            if (Math.abs(floors[i] - CALL) < Math.abs(floors[nearest] - CALL)) nearest = i;
        }
        System.out.println("nearest by distance: " + names[nearest] + " | cheapest by cost: " + names[cheapest]);
    }
}

