import java.util.*;

public class Main {
    // Idempotent bank: the txnId makes retried debits and reversals harmless
    static class Bank {
        int balance;
        Map<String, String> txns = new HashMap<>(); // txnId -> "DEBITED" or "REVERSED" (tombstone)
        Bank(int b) { balance = b; }

        String debit(String txn, int amount) {
            String state = txns.get(txn);
            if ("REVERSED".equals(state)) return "REFUSED"; // late debit after a reversal
            if (state == null) {
                balance -= amount;
                txns.put(txn, "DEBITED");
            }
            return "OK"; // repeat of the same id changes nothing
        }

        String reverse(String txn, int amount) {
            if ("DEBITED".equals(txns.get(txn))) balance += amount;
            txns.put(txn, "REVERSED"); // keep a tombstone even if never seen
            return "OK";
        }
    }

    public static void main(String[] args) {
        Bank bank = new Bank(100);
        System.out.println("start balance " + bank.balance);
        System.out.println("debit t1 50 -> " + bank.debit("t1", 50) + " " + bank.balance);
        System.out.println("debit t1 50 (retry) -> " + bank.debit("t1", 50) + " " + bank.balance);
        System.out.println("dispenser jammed, no cash given");
        System.out.println("reverse t1 -> " + bank.reverse("t1", 50) + " " + bank.balance);
        System.out.println("reverse t1 (retry) -> " + bank.reverse("t1", 50) + " " + bank.balance);
        System.out.println("late debit t1 -> " + bank.debit("t1", 50) + " " + bank.balance);
    }
}

