// Idempotent bank: the txnId makes retried debits and reversals harmless
class Bank {
  constructor(balance) {
    this.balance = balance;
    this.txns = new Map(); // txnId -> "DEBITED" or "REVERSED" (tombstone)
  }
  debit(txn, amount) {
    const state = this.txns.get(txn);
    if (state === "REVERSED") return "REFUSED"; // late debit after a reversal
    if (state === undefined) {
      this.balance -= amount;
      this.txns.set(txn, "DEBITED");
    }
    return "OK"; // repeat of the same id changes nothing
  }
  reverse(txn, amount) {
    if (this.txns.get(txn) === "DEBITED") this.balance += amount;
    this.txns.set(txn, "REVERSED"); // keep a tombstone even if never seen
    return "OK";
  }
}

