using namespace std;

// Idempotent bank: the txnId makes retried debits and reversals harmless
struct Bank {
    int balance;
    map<string, string> txns; // txnId -> "DEBITED" or "REVERSED" (tombstone)
    Bank(int b) : balance(b) {}

    string debit(const string& txn, int amount) {
        auto it = txns.find(txn);
        if (it != txns.end() && it->second == "REVERSED") return "REFUSED"; // late debit after reversal
        if (it == txns.end()) {
            balance -= amount;
            txns[txn] = "DEBITED";
        }
        return "OK"; // repeat of the same id changes nothing
    }

    string reverse(const string& txn, int amount) {
        auto it = txns.find(txn);
        if (it != txns.end() && it->second == "DEBITED") balance += amount;
        txns[txn] = "REVERSED"; // keep a tombstone even if never seen
        return "OK";
    }
};

int main() {
    Bank bank(100);
    cout << "start balance " << bank.balance << endl;
    string r = bank.debit("t1", 50);
    cout << "debit t1 50 -> " << r << " " << bank.balance << endl;
    r = bank.debit("t1", 50);
    cout << "debit t1 50 (retry) -> " << r << " " << bank.balance << endl;
    cout << "dispenser jammed, no cash given" << endl;
    r = bank.reverse("t1", 50);
    cout << "reverse t1 -> " << r << " " << bank.balance << endl;
    r = bank.reverse("t1", 50);
    cout << "reverse t1 (retry) -> " << r << " " << bank.balance << endl;
    r = bank.debit("t1", 50);
    cout << "late debit t1 -> " << r << " " << bank.balance << endl;
}

