using System;
using System.Collections.Generic;

class Bank
{
    public int Balance;
    Dictionary<string, string> txns = new Dictionary<string, string>(); // txnId -> DEBITED or REVERSED (tombstone)
    public Bank(int b) { Balance = b; }

    public string Debit(string txn, int amount)
    {
        string state;
        txns.TryGetValue(txn, out state);
        if (state == "REVERSED") return "REFUSED"; // late debit after a reversal
        if (state == null)
        {
            Balance -= amount;
            txns[txn] = "DEBITED";
        }
        return "OK"; // repeat of the same id changes nothing
    }

    public string Reverse(string txn, int amount)
    {
        string state;
        txns.TryGetValue(txn, out state);
        if (state == "DEBITED") Balance += amount;
        txns[txn] = "REVERSED"; // keep a tombstone even if never seen
        return "OK";
    }
}

class Program
{
    static void Main()
    {
        // Idempotent bank: the txnId makes retried debits and reversals harmless
        Bank bank = new Bank(100);
        Console.WriteLine("start balance " + bank.Balance);
        string r = bank.Debit("t1", 50);
        Console.WriteLine("debit t1 50 -> " + r + " " + bank.Balance);
        r = bank.Debit("t1", 50);
        Console.WriteLine("debit t1 50 (retry) -> " + r + " " + bank.Balance);
        Console.WriteLine("dispenser jammed, no cash given");
        r = bank.Reverse("t1", 50);
        Console.WriteLine("reverse t1 -> " + r + " " + bank.Balance);
        r = bank.Reverse("t1", 50);
        Console.WriteLine("reverse t1 (retry) -> " + r + " " + bank.Balance);
        r = bank.Debit("t1", 50);
        Console.WriteLine("late debit t1 -> " + r + " " + bank.Balance);
    }
}

