    static class Atm {
        boolean perSession;
        int attempts = 0;
        Atm(boolean perSession) { this.perSession = perSession; }

        void insertCard() {
            if (perSession) attempts = 0; // new session state starts clean
        }

        String enterPin(String pin) {
            if (pin.equals("1234")) { attempts = 0; return "OK"; } // correct PIN resets the count
            attempts++;
            return attempts >= 3 ? "RETAINED" : "WRONG(" + attempts + ")";
        }
    }

