        for (boolean perSession : new boolean[] {true, false}) {
            Atm atm = new Atm(perSession);
            System.out.println("counter in " + (perSession ? "session state" : "ATM field (bug)"));
            atm.insertCard(); // customer 1 fails twice and walks away
            String a = atm.enterPin("0000"), b = atm.enterPin("1111");
            System.out.println(" customer 1: " + a + " " + b);
            atm.insertCard(); // customer 2 types one typo, then the right PIN
            String c = atm.enterPin("9999"), d = atm.enterPin("1234");
            System.out.println(" customer 2: " + c + " " + d);
        }
    }
}

