public class Main {
    static int stock, version, sold;

    static boolean cas(int expectedVersion, int newStock) {
        if (version != expectedVersion) return false; // someone else committed first
        stock = newStock; version++;
        return true;
    }

    public static void main(String[] args) {
        // Check-then-act race replayed in a fixed order, then fixed with a version check (CAS)
        stock = 1; version = 0; sold = 0;
        int aStock = stock, bStock = stock;              // both buyers read stock = 1
        if (aStock > 0) { stock = aStock - 1; sold++; }  // A passes the guard and writes
        if (bStock > 0) { stock = bStock - 1; sold++; }  // B used its stale read too
        System.out.println("unsafe: stock " + stock + " sold " + sold);

        stock = 1; version = 0; sold = 0;
        int aVer = version; aStock = stock;              // both read the snapshot (version 0)
        int bVer = version; bStock = stock;
        if (aStock > 0 && cas(aVer, aStock - 1)) sold++;
        boolean ok = bStock > 0 && cas(bVer, bStock - 1);
        System.out.println("B first try: " + (ok ? "committed" : "rejected, retry"));
        if (!ok && stock > 0 && cas(version, stock - 1)) sold++; // retry on fresh data
        System.out.println("safe: stock " + stock + " sold " + sold + " version " + version);
    }
}

