import java.util.*;

public class Main {
    // The "database": machineId -> {status, version}
    static Map<String, Object[]> table = new LinkedHashMap<>();

    static boolean save(String mid, String status, int expectedVersion) {
        Object[] row = table.get(mid);
        if (row == null || (int) row[1] != expectedVersion) return false; // optimistic lock: stale writer loses
        table.put(mid, new Object[] {status, expectedVersion + 1});
        return true;
    }

    static String show(Object[] r) { return "[" + r[0] + ", " + r[1] + "]"; }
    static String b(boolean x) { return x ? "True" : "False"; }

    public static void main(String[] args) {
        // Persist the state NAME + version, move to DISPENSING before the side effect, recover after a crash
        table.put("m1", new Object[] {"IDLE", 0});
        System.out.println("insert coin : " + b(save("m1", "HAS_MONEY", 0)) + " " + show(table.get("m1")));
        System.out.println("select      : " + b(save("m1", "DISPENSING", 1)) + " " + show(table.get("m1"))); // BEFORE the motor runs
        System.out.println("stale write : " + b(save("m1", "IDLE", 1)) + " (version 1 is old)");
        System.out.println("-- crash: memory lost, only the table survives --");

        Map<String, String> recovery = Map.of("IDLE", "nothing to do", "HAS_MONEY", "refund coins",
            "DISPENSING", "check the motor sensor, refund if unsure"); // factory keyed by stored name
        for (String mid : new ArrayList<>(table.keySet())) {
            String status = (String) table.get(mid)[0];
            int ver = (int) table.get(mid)[1];
            System.out.println(mid + " rehydrated as " + status + " v" + ver + " -> " + recovery.get(status));
            if (status.equals("DISPENSING")) save(mid, "IDLE", ver); // reconcile and finish
        }
        System.out.println("after recovery: " + show(table.get("m1")));
    }
}

