#include <bits/stdc++.h>
using namespace std;

// The "database": machineId -> {status, version}
map<string, pair<string, int>> table_;

bool save(const string& mid, const string& status, int expectedVersion) {
    auto it = table_.find(mid);
    if (it == table_.end() || it->second.second != expectedVersion) return false; // stale writer loses
    table_[mid] = {status, expectedVersion + 1};
    return true;
}

string show(const pair<string, int>& r) { return "[" + r.first + ", " + to_string(r.second) + "]"; }
string b(bool x) { return x ? "True" : "False"; }

int main() {
    // Persist the state NAME + version, move to DISPENSING before the side effect, recover after a crash
    table_["m1"] = {"IDLE", 0};
    cout << "insert coin : " << b(save("m1", "HAS_MONEY", 0)) << " " << show(table_["m1"]) << endl;
    cout << "select      : " << b(save("m1", "DISPENSING", 1)) << " " << show(table_["m1"]) << endl; // BEFORE motor
    cout << "stale write : " << b(save("m1", "IDLE", 1)) << " (version 1 is old)" << endl;
    cout << "-- crash: memory lost, only the table survives --" << endl;

    map<string, string> recovery = {{"IDLE", "nothing to do"}, {"HAS_MONEY", "refund coins"},
        {"DISPENSING", "check the motor sensor, refund if unsure"}}; // factory keyed by stored name
    vector<string> ids;
    for (auto& kv : table_) ids.push_back(kv.first);
    for (auto& mid : ids) {
        string status = table_[mid].first;
        int ver = table_[mid].second;
        cout << mid << " rehydrated as " << status << " v" << ver << " -> " << recovery[status] << endl;
        if (status == "DISPENSING") save(mid, "IDLE", ver); // reconcile and finish
    }
    cout << "after recovery: " << show(table_["m1"]) << endl;
