using System;
using System.Collections.Generic;

class Program
{
    // The "database": machineId -> {status, version}
    static Dictionary<string, string> status = new Dictionary<string, string>();
    static Dictionary<string, int> versions = new Dictionary<string, int>();

    static bool Save(string mid, string newStatus, int expectedVersion)
    {
        if (!versions.ContainsKey(mid) || versions[mid] != expectedVersion) return false; // stale writer loses
        status[mid] = newStatus; versions[mid] = expectedVersion + 1;
        return true;
    }

    static string Show(string mid) { return "[" + status[mid] + ", " + versions[mid] + "]"; }
    static string B(bool x) { return x ? "True" : "False"; }

    static void Main()
    {
        // Persist the state NAME + version, move to DISPENSING before the side effect, recover after a crash
        status["m1"] = "IDLE"; versions["m1"] = 0;
        Console.WriteLine("insert coin : " + B(Save("m1", "HAS_MONEY", 0)) + " " + Show("m1"));
        Console.WriteLine("select      : " + B(Save("m1", "DISPENSING", 1)) + " " + Show("m1")); // BEFORE the motor runs
        Console.WriteLine("stale write : " + B(Save("m1", "IDLE", 1)) + " (version 1 is old)");
        Console.WriteLine("-- crash: memory lost, only the table survives --");

        Dictionary<string, string> recovery = new Dictionary<string, string> {
            { "IDLE", "nothing to do" }, { "HAS_MONEY", "refund coins" },
            { "DISPENSING", "check the motor sensor, refund if unsure" } }; // factory keyed by stored name
        foreach (string mid in new List<string>(status.Keys))
        {
            string st = status[mid];
            int ver = versions[mid];
            Console.WriteLine(mid + " rehydrated as " + st + " v" + ver + " -> " + recovery[st]);
            if (st == "DISPENSING") Save(mid, "IDLE", ver); // reconcile and finish
        }
        Console.WriteLine("after recovery: " + Show("m1"));
    }
}

