import java.util.*;

public class Main {
    static class Machine { int stock = 0; State state = new SoldOut(); }

    // Default-reject: every cell is "not now" unless a state overrides it
    static abstract class State {
        abstract String name();
        String insert(Machine m) { return "not now"; }
        String service(Machine m) { return "not now"; }
        String finish(Machine m) { return "not now"; }
        String restock(Machine m, int n) { return "not now"; }
        String cancel(Machine m) { return "not now"; }
    }
    static class Idle extends State {
        String name() { return "IDLE"; }
        String insert(Machine m) { m.state = new HasMoney(); return "coin accepted"; }
        String service(Machine m) { m.state = new Maintenance(); return "service mode"; }
    }
    static class SoldOut extends State {
        String name() { return "SOLD_OUT"; }
        String insert(Machine m) { return "coin returned"; }
        String service(Machine m) { m.state = new Maintenance(); return "service mode"; }
    }
    static class HasMoney extends State { // keeps default service(): never open with money in escrow
        String name() { return "HAS_MONEY"; }
        String cancel(Machine m) { m.state = new Idle(); return "coin returned"; }
    }
    static class Maintenance extends State {
        String name() { return "MAINTENANCE"; }
        String insert(Machine m) { return "coin returned"; }
        String restock(Machine m, int n) { m.stock += n; return "restocked " + n; }
        String finish(Machine m) { m.state = m.stock > 0 ? new Idle() : new SoldOut(); return "back in service"; }
    }

    static void show(String label, String msg, Machine m) {
        System.out.println(String.format("%-9s", label) + " -> " + msg + " [" + m.state.name() + "]");
    }

    public static void main(String[] args) {
        Machine m = new Machine();
        show("insert", m.state.insert(m), m);
        show("service", m.state.service(m), m);
        show("insert", m.state.insert(m), m);
        show("restock 2", m.state.restock(m, 2), m);
        show("finish", m.state.finish(m), m);
        show("insert", m.state.insert(m), m);
        show("service", m.state.service(m), m);
        show("cancel", m.state.cancel(m), m);
    }
}

