#include <bits/stdc++.h>
using namespace std;
struct Machine;

// Default-reject: every cell is "not now" unless a state overrides it
struct State {
    virtual ~State() {}
    virtual string name() = 0;
    virtual string insert(Machine&) { return "not now"; }
    virtual string service(Machine&) { return "not now"; }
    virtual string finish(Machine&) { return "not now"; }
    virtual string restock(Machine&, int) { return "not now"; }
    virtual string cancel(Machine&) { return "not now"; }
};
struct Machine { int stock = 0; unique_ptr<State> state; };

struct Idle : State { string name() override { return "IDLE"; } string insert(Machine&) override; string service(Machine&) override; };
struct SoldOut : State { string name() override { return "SOLD_OUT"; } string insert(Machine&) override { return "coin returned"; } string service(Machine&) override; };
struct HasMoney : State { string name() override { return "HAS_MONEY"; } string cancel(Machine&) override; }; // keeps default service()
struct Maintenance : State {
    string name() override { return "MAINTENANCE"; }
    string insert(Machine&) override { return "coin returned"; }
    string restock(Machine& m, int n) override { m.stock += n; return "restocked " + to_string(n); }
    string finish(Machine& m) override;
};

string Idle::insert(Machine& m) { m.state = make_unique<HasMoney>(); return "coin accepted"; }
