import java.util.*;

public class Main {
    static Map<String, String> parent = new HashMap<>();
    static Map<String, String> table = new HashMap<>();

    static List<String> chain(String s) { // state, its parent, grandparent...
        List<String> out = new ArrayList<>();
        while (s != null) { out.add(s); s = parent.get(s); }
        return out;
    }

    public static void main(String[] args) {
        // Hierarchical states: FIRE is written once on the OPERATIONAL parent and bubbles up from any child
        parent.put("IDLE", "OPERATIONAL"); parent.put("MOVING", "OPERATIONAL"); parent.put("DOORS_OPEN", "OPERATIONAL");
        table.put("IDLE|call", "MOVING"); table.put("MOVING|arrive", "DOORS_OPEN"); table.put("DOORS_OPEN|close", "IDLE");
        table.put("OPERATIONAL|FIRE", "FIRE_RECALL"); table.put("FIRE_RECALL|reset", "IDLE");

        String cur = "IDLE";
        for (String event : new String[] {"call", "arrive", "FIRE", "arrive", "reset"}) {
            String s = cur, target = null;
            while (s != null && target == null) { // bubble up until some ancestor handles the event
                target = table.get(s + "|" + event);
                if (target == null) s = parent.get(s);
            }
            if (target == null) { System.out.println(String.format("%-6s", event) + ": " + cur + " ignored"); continue; }
            List<String> a = chain(cur), b = chain(target);
            String lca = null; // lowest common ancestor
            for (String x : a) if (b.contains(x)) { lca = x; break; }
            List<String> exits = lca == null ? a : a.subList(0, a.indexOf(lca));
            List<String> enters = new ArrayList<>(lca == null ? b : b.subList(0, b.indexOf(lca)));
            Collections.reverse(enters);
            System.out.println(String.format("%-6s", event) + ": " + cur + " -> " + target
                + " | exit " + String.join(",", exits) + " | enter " + String.join(",", enters));
            cur = target;
        }
    }
}

