#include <bits/stdc++.h>
using namespace std;
map<string, string> parent_;   // empty string means "no parent"
map<string, string> table_;

vector<string> chain(string s) { // state, its parent, grandparent...
    vector<string> out;
    while (!s.empty()) { out.push_back(s); s = parent_[s]; }
    return out;
}

string join(const vector<string>& v) {
    string r;
    for (size_t i = 0; i < v.size(); i++) r += (i ? "," : "") + v[i];
    return r;
}

int main() {
    // Hierarchical states: FIRE is written once on the OPERATIONAL parent and bubbles up from any child
    parent_ = {{"IDLE", "OPERATIONAL"}, {"MOVING", "OPERATIONAL"}, {"DOORS_OPEN", "OPERATIONAL"}};
    table_ = {{"IDLE|call", "MOVING"}, {"MOVING|arrive", "DOORS_OPEN"}, {"DOORS_OPEN|close", "IDLE"},
              {"OPERATIONAL|FIRE", "FIRE_RECALL"}, {"FIRE_RECALL|reset", "IDLE"}};
    string cur = "IDLE";
    for (string event : {"call", "arrive", "FIRE", "arrive", "reset"}) {
        string s = cur, target;
        while (!s.empty() && target.empty()) { // bubble up until some ancestor handles the event
            auto it = table_.find(s + "|" + event);
            if (it != table_.end()) target = it->second; else s = parent_[s];
        }
        cout << left << setw(6) << event << ": ";
        if (target.empty()) { cout << cur << " ignored" << endl; continue; }
        vector<string> a = chain(cur), b = chain(target), exits, enters;
        string lca; // lowest common ancestor
        for (auto& x : a) if (find(b.begin(), b.end(), x) != b.end()) { lca = x; break; }
        for (auto& x : a) { if (x == lca) break; exits.push_back(x); }
        for (auto& x : b) { if (x == lca) break; enters.push_back(x); }
        reverse(enters.begin(), enters.end());
        cout << cur << " -> " << target << " | exit " << join(exits) << " | enter " << join(enters) << endl;
        cur = target;
    }
}

