using System.Collections.Generic;

class Program
{
    static Dictionary<string, string> parent = new Dictionary<string, string>();
    static Dictionary<string, string> table = new Dictionary<string, string>();

    static List<string> Chain(string s) // state, its parent, grandparent...
    {
        List<string> outp = new List<string>();
        while (s != null) { outp.Add(s); string p; s = parent.TryGetValue(s, out p) ? p : null; }
        return outp;
    }

    static void Main()
    {
        // Hierarchical states: FIRE is written once on the OPERATIONAL parent and bubbles up from any child
        parent["IDLE"] = "OPERATIONAL"; parent["MOVING"] = "OPERATIONAL"; parent["DOORS_OPEN"] = "OPERATIONAL";
        table["IDLE|call"] = "MOVING"; table["MOVING|arrive"] = "DOORS_OPEN"; table["DOORS_OPEN|close"] = "IDLE";
        table["OPERATIONAL|FIRE"] = "FIRE_RECALL"; table["FIRE_RECALL|reset"] = "IDLE";

        string cur = "IDLE";
        foreach (string ev in new string[] { "call", "arrive", "FIRE", "arrive", "reset" })
        {
            string s = cur, target = null;
            while (s != null && target == null) // bubble up until some ancestor handles the event
            {
                string t;
                if (table.TryGetValue(s + "|" + ev, out t)) target = t;
                else { string p; s = parent.TryGetValue(s, out p) ? p : null; }
            }
            if (target == null) { Console.WriteLine(ev.PadRight(6) + ": " + cur + " ignored"); continue; }
            List<string> a = Chain(cur), b = Chain(target);
            string lca = null; // lowest common ancestor
            foreach (string x in a) if (b.Contains(x)) { lca = x; break; }
            List<string> exits = lca == null ? a : a.GetRange(0, a.IndexOf(lca));
            List<string> enters = lca == null ? new List<string>(b) : b.GetRange(0, b.IndexOf(lca));
            enters.Reverse();
            Console.WriteLine(ev.PadRight(6) + ": " + cur + " -> " + target
                + " | exit " + string.Join(",", exits) + " | enter " + string.Join(",", enters));
            cur = target;
        }
    }
}

