public class Main {
    static long seed = 42;
    static long rnd() { seed = seed * 48271 % 2147483647; return seed; } // tiny deterministic generator

    public static void main(String[] args) {
        // Randomized event sequence checking invariants after every step (price 2, coins of 1)
        int stock = 5, credit = 0, coinsIn = 0, refunded = 0, sold = 0, violations = 0;
        for (int step = 0; step < 10000; step++) {
            long op = rnd() % 3;
            if (op == 0) { credit++; coinsIn++; }                                  // insert a coin
            else if (op == 1 && credit >= 2 && stock > 0) { stock--; credit -= 2; sold++; } // guard first, then act
            else if (op == 2) { refunded += credit; credit = 0; }                  // cancel: give the credit back
            boolean ok = stock >= 0 && credit >= 0 && coinsIn == 2 * sold + refunded + credit;
            if (!ok) violations++;
        }
        System.out.println("events 10000 sold " + sold + " stock " + stock + " credit " + credit);
        System.out.println("coins in " + coinsIn + " = 2*sold + " + refunded + " refunded + " + credit + " credit");
        System.out.println("invariant violations: " + violations);
    }
}

